std::istringstream in("4 3 1\n1 2\n2 3\n1 4\n");
std::ostringstream out;
std::streambuf* cout_old = std::cout.rdbuf(out.rdbuf());
solve(in, out);
std::cout.rdbuf(cout_old);
CHECK_EQ(out.str(), std::string("0 1 2 1\n"));

